function numberOfCuts(n) {
  if (n === 1) return 0;
  // Equal slices need n boundary rays spaced 360/n degrees apart; ray i sits at angle 2i in units of 180/n.
  const covered = new Array(n).fill(false);
  let cuts = 0;
  for (let ray = 0; ray < n; ray++) {
    if (covered[ray]) continue;
    covered[ray] = true;
    cuts++;
    // The opposite direction is at angle 2*ray + n; one diameter covers it too if it is also a boundary ray.
    const opposite = 2 * ray + n;
    if (opposite % 2 === 0) covered[(opposite / 2) % n] = true;
  }
  return cuts;
}

